Here is the root cause:
The deadlock occurs because `shstk_pop_sigframe()` in `arch/x86/kernel/shstk.c` holds the mmap read lock while reading the shadow stack signal frame from userspace via `get_shstk_data()`. If this read triggers a page fault, the fault handler attempts to acquire the same mmap read lock recursively. While recursive read locks normally succeed, a concurrent writer waiting for the lock can cause the recursive read lock to fail, leading to a deadlock where both the writer and the fault handler are blocked.

Here is the patch:

 static int shstk_pop_sigframe(unsigned long *ssp)
 {
-	struct vm_area_struct *vma;
 	unsigned long token_addr;
-	bool need_to_check_vma;
-	int err = 1;
+	unsigned int seq;

 	/*
 	 * It is possible for the SSP to be off the end of a shadow stack by 4
 	 * or 8 bytes. If the shadow stack is at the start of a page or 4 bytes
 	 * before it, it might be this case, so check that the address being
 	 * read is actually shadow stack.
 	 */
 	if (!IS_ALIGNED(*ssp, 8))
 		return -EINVAL;

-	need_to_check_vma = PAGE_ALIGN(*ssp) == *ssp;
+	do {
+		struct vm_area_struct *vma;
+		bool valid_vma;
+		int err;

-	if (need_to_check_vma)
 		if (mmap_read_lock_killable(current->mm))
 			return -EINTR;

-	err = get_shstk_data(&token_addr, (unsigned long __user *)*ssp);
-	if (unlikely(err))
-		goto out_err;
-
-	if (need_to_check_vma) {
 		vma = find_vma(current->mm, *ssp);
-		if (!vma || !(vma->vm_flags & VM_SHADOW_STACK)) {
-			err = -EFAULT;
-			goto out_err;
-		}
-
+		valid_vma = vma && (vma->vm_flags & VM_SHADOW_STACK);
+
+		/*
+		 * VMAs can change between get_shstk_data() and find_vma().
+		 * Watch for changes and ensure that 'token_addr' comes from
+		 * 'vma' by recording a seqcount.
+		 *
+		 * Ignore the return value of mmap_lock_speculate_try_begin()
+		 * because the mmap lock excludes the possibility of writers.
+		 */
+		mmap_lock_speculate_try_begin(current->mm, &seq);
 		mmap_read_unlock(current->mm);
-	}
+
+		if (!valid_vma)
+			return -EINVAL;
+
+		err = get_shstk_data(&token_addr, (unsigned long __user *)*ssp);
+		if (err)
+			return err;
+	} while (mmap_lock_speculate_retry(current->mm, seq));

 	/* Restore SSP aligned? */
 	if (unlikely(!IS_ALIGNED(token_addr, 8)))
 		return -EINVAL;

 	/* SSP in userspace? */
 	if (unlikely(token_addr >= TASK_SIZE_MAX))
 		return -EINVAL;

 	*ssp = token_addr;

 	return 0;
-out_err:
-	if (need_to_check_vma)
-		mmap_read_unlock(current->mm);
-	return err;
 }



